export function generateCustomXml(config: BlogConfig): string {
  let xml = DEFAULT_XML_CODE;
  xml = xml.replace(/Gandzar Subagja/g, config.authorName);
  xml = xml.replace(/gandzar@gmail\.com/g, config.email);
  xml = xml.replace(/Cuman Konten Kreator &amp; Fullstack Specialist biasa yang suka ngoprek sistem\./g, config.bio);
  xml = xml.replace(/mvkzpprq/g, config.formspreeId);
  xml = xml.replace(/G-XXXXXXXXXX/g, config.ga4Id);
  if (config.avatarUrl) {
    xml = xml.replace(/https:\/\/blogger\.googleusercontent\.com\/img\/b\/R29vZ2xl\/AVvXsEhQr_6Q2B6xIcyzYVfd3D5QpeH0YVaPzGM01Wgsp7msgcZ7X-dKoIdhdOFpO0gWdSxdaZhU-Tzzy_GyA39GF6svcSW9UK-1E39kZMqMjoNizs-Nv65xy_aY6vaFNh4MNiw5q5XphZbilf5uH6DUxQ0oMaGLMDtMK1E34r1GW5FCGVM0hskGWexFUDSZ7RA\/s800\/icon_untukdi_aboutthisapp\.webp/g, config.avatarUrl);
  }
  return xml;
}
